package br.com.portal.controller;
import br.com.portal.dto.*; import br.com.portal.model.UnidadeCurricular; import br.com.portal.service.UCService; import jakarta.servlet.http.HttpSession; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/ucs") public class UnidadeCurricularController {private final UCService s;public UnidadeCurricularController(UCService s){this.s=s;}
 @GetMapping("/turma/{turmaId}") List<UnidadeCurricular> listar(@PathVariable Long turmaId,HttpSession x){return s.listar(turmaId,x);} @GetMapping("/{id}") UnidadeCurricular buscar(@PathVariable Long id,HttpSession x){return s.buscar(id,x);} @PostMapping("/turma/{turmaId}") ResponseEntity<UnidadeCurricular> criar(@PathVariable Long turmaId,@Valid @RequestBody UCRequest r,HttpSession x){return ResponseEntity.status(201).body(s.criar(turmaId,r,x));} @PutMapping("/{id}") UnidadeCurricular atualizar(@PathVariable Long id,@Valid @RequestBody UCRequest r,HttpSession x){return s.atualizar(id,r,x);} @DeleteMapping("/{id}") ResponseEntity<Void> excluir(@PathVariable Long id,HttpSession x){s.excluir(id,x);return ResponseEntity.noContent().build();}}
